begin;
create extension if not exists pgtap with schema extensions;
select plan(16);
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000001'),('00000000-0000-4000-8000-000000000002');
insert into public.profiles(user_id,display_name) values ('00000000-0000-4000-8000-000000000001','One'),('00000000-0000-4000-8000-000000000002','Two');
insert into public.user_preferences(user_id) select id from auth.users where id in ('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002');
select is((select count(*)::integer from public.kana_catalog),214,'catalog matches bundled kana');
select ok(not has_function_privilege('authenticated','public.commit_learning(uuid,bigint,jsonb,jsonb,jsonb,text,bigint)','execute'),'users cannot commit canonical state');
select ok(not has_function_privilege('anon','public.learning_snapshot(uuid)','execute'),'anonymous cannot read snapshots');
select ok(not has_table_privilege('authenticated','public.review_events','insert'),'users cannot insert events directly');
select ok(not has_table_privilege('authenticated','public.user_card_progress','update'),'users cannot overwrite canonical progress');
select ok(not has_function_privilege('authenticated','public.reset_learning(uuid,text)','execute'),'users cannot invoke administrative reset directly');
select ok(not has_function_privilege('authenticated','public.commit_learning_base(uuid,bigint,jsonb,jsonb,jsonb,text)','execute'),'legacy helper does not bypass generation fencing');
select ok(not has_function_privilege('authenticated','public.learning_snapshot_base(uuid)','execute'),'snapshot helper remains private');
select ok(not has_table_privilege('authenticated','public.learning_reset_requests','select'),'reset identities remain private');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*)::integer from public.profiles),1,'RLS only exposes own profile');
select is((select count(*)::integer from public.user_preferences),1,'RLS only exposes own preferences');
with changed as (update public.profiles set display_name='Intruder' where user_id='00000000-0000-4000-8000-000000000002' returning *) select is(count(*)::integer,0,'cannot update another profile') from changed;
reset role;
set local role service_role;
select lives_ok($$select public.commit_learning('00000000-0000-4000-8000-000000000001',0,'[]','[]','[{"id":"setting-one","patch":{"theme":"dark"}}]')$$,'service commits settings');
select lives_ok($$select public.commit_learning('00000000-0000-4000-8000-000000000001',1,'[]','[]','[{"id":"setting-two","patch":{"theme":"light"}}]')$$,'later setting wins');
select lives_ok($$select public.commit_learning('00000000-0000-4000-8000-000000000001',2,'[]','[]','[{"id":"setting-one","patch":{"theme":"dark"}}]')$$,'lost-response retry is safe');
select is((select theme from public.user_preferences where user_id='00000000-0000-4000-8000-000000000001'),'light','retry does not overwrite a newer setting');
reset role;
select * from finish();
rollback;
